    $femalesPerDecade := $withDecades[gender="female"]{ decade: $count($) };\
    $femalesSeries := $map($decades, function($d) { $lookup($femalesPerDecade, $d) });\
    { "results": $withDecades, "data": $withDecades, "decades": $decades, "malesSeries": $malesSeries, "femalesSeries": $femalesSeries }\
  )',
  children: [
    { type: 'json', path: '$.malesSeries', style: { display: 'none' }},
    {
      type: 'view',
      style: { flexDirection: 'column', gap: 40 },
      children: [
        {
          type: 'table',
          path: '$.results[[0..10]]', 
          columns: [
            {
              header: 'Id',
              accessor: 'id.value',
            },
            {
              header: 'Name',
              accessor: 'name.first',
              cell: {
                type: 'view',
                style: {
                  alignItems: 'center',
                  gap: 8,
                  fontWeight: '600',
                  whiteSpace: 'nowrap',
                },
                children: [
                  {
                    type: 'image',
                    style: {
                      width: 40,
                      height: 'auto',
                      borderRadius: '50%',
                    },
                    src: '{{picture.thumbnail}}',
                  },
                  '{{name.title}} {{name.first}} {{name.last}}',
                ],
              },
            },
            { 
              header: 'Birth',
              accessor: 'dob.age',
              cell: '{{$formatDate(dob.date)}} ({{dob.age}} y)',
            },
            { 
              header: 'Decade',
              accessor: 'decade',
            },
            {
              header: 'Registered',
              accessor: 'registered.age',
              cell: '{{$formatDate(registered.date)}} ({{registered.age}} y)',
            },
            {
              header: 'Gender',
              accessor: 'gender',
              cell: {
                type: 'text', 
                style: { fontSize: 20 },
                text: '{{$.gender="female"?"♂":"♀"}}',
              }
            },
            {
              header: 'Location',
              accessor: 'location.state',
