            },
            {
              header: 'Phone',
              accessor: 'phone',
            },
            {
              header: 'Cell',
              accessor: 'cell',
            },
          ],
        },    
        {
          type: 'view',
          children: [
            {
              type: 'chart',
              options: {
                chart: {
                  //width: 200,              
                  height: 200,
                },
                cartesianGrid: {
                  stroke: "#eee",
                  strokeDasharray:"5 5",
                  vertical: false
                },
                xAxis: {
                  axisLine: false,
                  tickLine: false
                },
                yAxis: {
                  axisLine: false,
                  tickLine: false
                },
              },
              data: {
                categories: '$.decades',
                series: [
                  {
                    chartType: 'bar',
                    name: 'Males',
                    stackId: 'a',
                    fill: '#FFBB28',
                    data: '$.malesSeries',
                  },
                  {
                    chartType: 'bar',
                    name: 'Females',
                    stackId: 'a',
                    fill: '#00C49F',
                    data: '$.femalesSeries',
                  },
                ],
              },
            },
          ],
          style: {
            flexDirection: 'column',
            height: '100%'
          },
        },      
      ]
    }
  ]
